exec:
if (!pm.environment.get("existing_app_client_id") || !pm.environment.get("existing_app_client_secret")) {
    console.log("SKIP " + pm.info.requestName + ": existing_app_client_id/secret not set in the environment");
    pm.collectionVariables.set("skipped_list",
        (pm.collectionVariables.get("skipped_list") || "") + "|" + pm.info.requestName);
    pm.execution.skipRequest();
}

pm.test("Existing app token issued", function () {
    pm.expect(pm.response.code,
        "expected 200 -- check existing_app_client_id/secret and that the app's grant types include client_credentials. " +
        "[NOTE] this request gates 9.2 -- when it fails, 9.2 is SKIPPED.").to.eql(200);
});

if (pm.response.code === 200) {
    pm.collectionVariables.set("existing_api_token", pm.response.json().access_token);
}

if (!pm.collectionVariables.get("existing_api_token")) {
    console.log("SKIP " + pm.info.requestName + ": existing_api_token is empty");
    pm.collectionVariables.set("skipped_list",
        (pm.collectionVariables.get("skipped_list") || "") + "|" + pm.info.requestName);
    pm.execution.skipRequest();
}

const code = pm.response.code;
let why = "expected 200 but got " + code + ". ";
if (code === 404)      why += "The existing API is not deployed on this gateway, or existing_api_path / vhost is wrong.";
else if (code === 401) why += "The gateway rejected the token -- check Key Manager / JWKS reachability from the gateway.";
else if (code === 403) why += "The app is not subscribed, or the subscription is not visible to the gateway.";
else if (code >= 500)  why += "The gateway served the API but the backend call failed.";

pm.test("Existing API is served by the gateway", function () {
    pm.expect(code, why).to.eql(200);
});

if (!pm.collectionVariables.get("existing_api_token")) {
    console.log("SKIP " + pm.info.requestName + ": existing_api_token is empty");
    pm.collectionVariables.set("skipped_list",
        (pm.collectionVariables.get("skipped_list") || "") + "|" + pm.info.requestName);
}

// ---------------------------------------------------------------------------
// End-of-run summary. Newman's table shows failures but NOT skips, so a run can
// report "0 failed" while quietly having executed far fewer checks. This prints
// what was skipped and why, for whoever is reading the run.
// ---------------------------------------------------------------------------
const skipped = (pm.collectionVariables.get("skipped_list") || "")
                  .split("|").filter(x => x.length > 0);
console.log("===== RUN SUMMARY =====");
if (skipped.length === 0) {
    console.log("SKIPPED: none -- every request executed.");
} else {
    console.log("SKIPPED (" + skipped.length + ") -- these did NOT run, so the check");
    console.log("count below is LOWER than a full run. Fix the failure above first:");
    skipped.forEach(s => console.log("   - " + s));
}
console.log("========================");
pm.collectionVariables.unset("skipped_list");

if (!pm.collectionVariables.get("existing_api_token")) {
    pm.execution.skipRequest();
}

pm.test("Existing app token revoked", function () {
    pm.expect(pm.response.code,
        "expected 200 -- check existing_app_client_id/secret; the revoke must use the same client that issued the token.")
      .to.eql(200);
});

pm.collectionVariables.unset("existing_api_token");
